declare target uuid; p record;
begin
  perform private.social_hangout_mutation_lock();
  delete from private.safety_reconciliation_effects;
  insert into private.safety_reconciliation_effects(hangout_id,account_id,effect)
  with conflict as (
    select h.id hangout_id,h.host_id,b.blocker_id,b.blocked_id
    from private.people_blocks b
    join public.hangout_participants x on x.account_id=b.blocker_id and x.state='joined'
    join public.hangout_participants y on y.hangout_id=x.hangout_id
      and y.account_id=b.blocked_id and y.state='joined'
    join public.hangouts h on h.id=x.hangout_id
  ), effects as (
    select hangout_id,blocked_id account_id,'removed'::text effect from conflict
      where blocker_id=host_id and blocked_id<>host_id
    union all
    select hangout_id,blocker_id,'left' from conflict where blocker_id<>host_id
  )
  select hangout_id,account_id,
    case when bool_or(effect='removed') then 'removed' else 'left' end
  from effects group by hangout_id,account_id;
  -- New writes cannot alter membership while the shared lock is held. Parent
  -- rows still have a documented ascending lock order for gate/row writers.
  for target in select distinct hangout_id from private.safety_reconciliation_effects order by hangout_id loop
    perform 1 from public.hangouts where id=target for update;
  end loop;
  -- Record overlap from the original roster, before the first state change.
  for p in select distinct hangout_id,account_id from private.safety_reconciliation_effects
      order by hangout_id,account_id loop
    perform private.safety_record_joined_overlap(p.hangout_id,p.account_id);
  end loop;
  for p in select * from private.safety_reconciliation_effects order by hangout_id,account_id loop
    update public.hangout_participants set state=p.effect,
      left_at=case when p.effect='left' then clock_timestamp() else left_at end,
      removed_at=case when p.effect='removed' then clock_timestamp() else removed_at end,
      updated_at=clock_timestamp()
    where hangout_id=p.hangout_id and account_id=p.account_id and state='joined';
  end loop;
  delete from private.safety_reconciliation_effects;
end;

begin
  if not exists(select 1 from public.hangout_participants own
    where own.hangout_id=p_hangout and own.account_id=p_actor and own.state='joined') then
    return;
  end if;
  insert into private.hangout_peer_provenance(hangout_id,low_id,high_id)
  select p_hangout,least(p_actor,p.account_id),greatest(p_actor,p.account_id)
  from public.hangout_participants p
  where p.hangout_id=p_hangout and p.state='joined' and p.account_id<>p_actor
  on conflict do nothing;
end;

declare original_role text:=current_setting('role',true); reason text:=private.profile_trim(p_reason); old private.pilot_admission_managers%rowtype; next_revision bigint;
begin
 if session_user<>'postgres' or original_role not in ('none','postgres') then raise exception 'Pilot management unavailable' using errcode='42501'; end if;
 perform private.pilot_lock_management(null,p_account_id,null,true);
 if p_account_id is null or p_state is null or p_state not in ('active','revoked') or p_expected_revision is null or p_expected_revision<0
  or reason is null or char_length(reason) not between 1 and 2000 or p_request_id is null
  or not exists(select 1 from public.accounts where id=p_account_id) then raise exception 'Pilot management unavailable' using errcode='42501'; end if;
 select * into old from private.pilot_admission_managers where account_id=p_account_id;
 if coalesce(old.revision,0)<>p_expected_revision then raise exception 'Pilot management unavailable' using errcode='42501'; end if;
 next_revision:=case when old.state=p_state then old.revision else coalesce(old.revision,0)+1 end;
 if old.account_id is null then insert into private.pilot_admission_managers(account_id,state,revision) values(p_account_id,p_state,next_revision);
 elsif old.state<>p_state then update private.pilot_admission_managers set state=p_state,revision=next_revision,updated_at=clock_timestamp() where account_id=p_account_id; end if;
 insert into private.pilot_manager_audit(account_id,executor_session_user,executor_original_role,executor_backend_pid,previous_state,new_state,previous_revision,new_revision,reason,request_id)
 values(p_account_id,session_user,original_role,pg_backend_pid(),old.state,p_state,coalesce(old.revision,0),next_revision,reason,p_request_id);
 return next_revision;
end;

begin
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'Safety operation unavailable' using errcode='42501';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(16016,1);
end;

declare campus uuid;
begin
  if new.email_confirmed_at is not null and new.email ~ '^[^@[:space:]]+@[^@[:space:]]+$' then
    select id into campus from public.universities
    where slug = 'unc-chapel-hill' and active
      and lower(split_part(new.email, '@', 2)) = any(allowed_email_domains);
  end if;
  if campus is null then
    delete from public.university_memberships where user_id = new.id;
  else
    insert into public.university_memberships(user_id, university_id, verified_at, verification_email)
    values (new.id, campus, new.email_confirmed_at, lower(new.email))
    on conflict (user_id) do update set university_id = excluded.university_id,
      verified_at = excluded.verified_at, verification_email = excluded.verification_email;
  end if;
  return new;
end;

declare item jsonb;
begin
 if jsonb_typeof(items)<>'array' then return false; end if;
 if jsonb_array_length(items)>3 then return false; end if;
 for item in select value from jsonb_array_elements(items) loop
   if jsonb_typeof(item)<>'object' then return false; end if;
   if (select count(*) from jsonb_object_keys(item))<>2
      or not item ?& array['question','answer']
      or jsonb_typeof(item->'question')<>'string' or jsonb_typeof(item->'answer')<>'string'
      or length(private.profile_trim(item->>'question')) not between 1 and 120
      or length(private.profile_trim(item->>'answer')) not between 1 and 500
      or item->>'question'<>private.profile_trim(item->>'question') or item->>'answer'<>private.profile_trim(item->>'answer') then return false; end if;
 end loop;
 return true;
end;

begin
 if length(private.profile_trim(value))>2000 then
   raise exception 'Invalid private meeting instructions' using errcode='22023';
 end if;
end;

declare path text;
begin
 -- A KEY SHARE lock lasts through commit. A concurrent delete either waits,
 -- fails serialization at stronger isolation, or deadlocks and aborts safely.
 for path in select unnest(array_remove(array_prepend(new.primary_photo_path,new.additional_photo_paths),null)) order by 1 loop
   perform 1 from storage.objects o where o.bucket_id='profile-photos' and o.name=path
     and o.owner_id=new.user_id::text and split_part(o.name,'/',1)=new.user_id::text for key share;
   if not found then raise exception 'Photos must be existing owned private objects' using errcode='23514'; end if;
 end loop;
 return new;
end;

declare actor uuid:=auth.uid(); h public.hangouts; current_answer private.attendance_answers%rowtype;
  opened_at timestamptz; checked_at timestamptz;
begin
  if current_setting('transaction_isolation')<>'read committed' or actor is null
    or p_hangout_id is null or p_attended is null or p_expected_revision is null then
    raise exception 'Attendance unavailable' using errcode='42501';
  end if;
  perform private.social_hangout_mutation_lock();
  select * into h from public.hangouts where id=p_hangout_id for update;
  if not found then raise exception 'Attendance unavailable' using errcode='42501'; end if;
  -- Lock order: global advisory, parent, source gate, attendance gate,
  -- account, participant, existing answer. Each gate SHARE lock prevents
  -- a revocation from committing until this answer has committed.
  perform 1 from private.hangout_feature_gate where singleton for share;
  perform 1 from private.attendance_feature_gate where singleton for share;
  perform 1 from public.accounts where id=actor for share;
  perform 1 from public.hangout_participants p
    where p.hangout_id=h.id and p.account_id=actor for share;
  select a.* into current_answer from private.attendance_answers a
    where a.hangout_id=h.id and a.account_id=actor for update;
  opened_at:=coalesce(h.ends_at,h.starts_at+interval '2 hours');
  checked_at:=clock_timestamp();
  if not exists(select 1 from private.hangout_feature_gate where singleton and enabled)
    or not exists(select 1 from private.attendance_feature_gate where singleton and enabled)
    or not exists(select 1 from public.accounts where id=actor and status='active')
    or not exists(select 1 from public.hangout_participants p
      where p.hangout_id=h.id and p.account_id=actor)
    or exists(select 1 from private.hangout_disables d where d.hangout_id=h.id)
    or (h.status='cancelled' and h.updated_at<h.starts_at)
    or checked_at<opened_at or checked_at>=opened_at+interval '30 days' then
    raise exception 'Attendance unavailable' using errcode='42501';
  end if;
  if current_answer.hangout_id is not null and current_answer.attended=p_attended then
    return query select current_answer.hangout_id,current_answer.attended,
      current_answer.revision,current_answer.answered_at;
    return;
  end if;
  if p_expected_revision<>coalesce(current_answer.revision,0) then
    raise exception 'Attendance unavailable' using errcode='42501';
  end if;
  insert into private.attendance_answers as a(hangout_id,account_id,attended,revision,answered_at)
    values(h.id,actor,p_attended,p_expected_revision+1,checked_at)
    on conflict on constraint attendance_answers_pkey do update
      set attended=excluded.attended,revision=excluded.revision,answered_at=excluded.answered_at;
  return query select h.id,p_attended,p_expected_revision+1,checked_at;
end;

declare
  actor uuid; r private.safety_reports%rowtype;
  c private.moderation_cases%rowtype; prior private.moderation_requests%rowtype;
  target public.accounts%rowtype; normalized_reason text; fingerprint text;
  required_role text; next_status text; campus uuid; saved_sanction uuid;
begin
  -- Stage A order: moderation advisory lock, gate, actor account and role,
  -- stored report, target account, request UUID, case, membership, writes.
  -- The target account UPDATE lock also excludes concurrent FK key-share
  -- platform-role insertion. It conflicts with student evidence SHARE locks.
  actor:=private.moderation_actor();
  normalized_reason:=private.profile_trim(p_reason);
  if p_report_id is null or p_request_id is null
    or p_expected_case_revision is null or p_expected_case_revision<0
    or p_action is null or p_action not in ('suspend','ban','reinstate')
    or normalized_reason is null or char_length(normalized_reason) not between 1 and 2000
    or not private.moderation_report_allowed(actor,p_report_id,true) then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  select * into r from private.safety_reports where id=p_report_id;
  if r.target_type<>'user' then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  select * into target from public.accounts where id=r.target_id;
  if not found or exists(select 1 from public.platform_roles where user_id=r.target_id) then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  required_role:=case when p_action='suspend' then 'moderator' else 'admin' end;
  if not exists(select 1 from public.platform_roles where user_id=actor and
    (role='admin' or (required_role='moderator' and role='moderator'))) then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  fingerprint:='account:'||md5(jsonb_build_array(p_report_id,
    p_expected_case_revision,p_action,normalized_reason)::text);
  perform pg_advisory_xact_lock(hashtextextended(actor::text||p_request_id::text,17017));
  select * into prior from private.moderation_requests
    where operator_id=actor and request_id=p_request_id;
  if found then
    if prior.fingerprint<>fingerprint then
      raise exception 'Moderation unavailable' using errcode='42501'; end if;
    -- Current operator/gate/conflict/target-role checks occurred above. The
    -- replay reveals only the original minimal result, not current status.
    select s.new_status into account_status from private.account_sanctions s
      where s.operator_id=actor and s.request_id=p_request_id
        and s.report_id=p_report_id;
    if account_status is null then
      raise exception 'Moderation unavailable' using errcode='42501'; end if;
    case_state:=prior.result_state; revision:=prior.result_revision;
    return next; return;
  end if;
  select * into c from private.moderation_cases
    where report_id=p_report_id for update;
  if not found or c.state<>'in_review'
    or c.revision<>p_expected_case_revision then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  next_status:=case p_action when 'suspend' then 'suspended'
    when 'ban' then 'banned' else 'active' end;
  if (p_action='suspend' and target.status<>'active')
    or (p_action='ban' and target.status not in ('active','suspended'))
    or (p_action='reinstate' and target.status not in ('suspended','banned')) then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  select university_id into campus from public.university_memberships
    where user_id=r.target_id for share;
  -- The account, role, case, gate, report and current membership are held
  -- through commit. Recheck after every possible lock wait.
  if not exists(select 1 from private.moderation_feature_gate where singleton and enabled)
    or not exists(select 1 from public.accounts where id=actor and status='active')
    or not exists(select 1 from public.platform_roles where user_id=actor and
      (role='admin' or (required_role='moderator' and role='moderator')))
    or exists(select 1 from public.platform_roles where user_id=r.target_id)
    or not exists(select 1 from public.accounts where id=r.target_id
      and status=target.status) then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  insert into private.account_sanctions(report_id,subject_id,operator_id,request_id,
    action,previous_status,new_status,subject_campus_id,reason)
    values(r.id,r.target_id,actor,p_request_id,p_action,target.status,
      next_status,campus,normalized_reason) returning id into saved_sanction;
  update public.accounts set status=next_status where id=r.target_id;
  update private.moderation_cases set state='closed',revision=c.revision+1,
    note=normalized_reason,disposition='action_taken',duplicate_report_id=null,
    sanction_id=saved_sanction where report_id=r.id;
  insert into private.moderation_requests(operator_id,request_id,fingerprint,
    report_id,result_state,result_revision)
    values(actor,p_request_id,fingerprint,r.id,'closed',c.revision+1);
  insert into private.moderation_audit(operator_id,action,report_id,
    subject_target_type,subject_target_id,subject_campus_id,request_id,
    previous_state,new_state,previous_revision,new_revision,reason,sanction_id,
    previous_account_status,new_account_status)
    values(actor,p_action,r.id,'user',r.target_id,campus,p_request_id,
      c.state,'closed',c.revision,c.revision+1,normalized_reason,saved_sanction,
      target.status,next_status);
  case_state:='closed'; revision:=c.revision+1; account_status:=next_status;
  return next;
end;

declare actor uuid; r private.safety_reports%rowtype; h public.hangouts%rowtype;
  c private.moderation_cases%rowtype; prior private.moderation_requests%rowtype;
  normalized_reason text; fingerprint text; saved_disable uuid;
begin
  -- Shared social lock precedes the parent. Stage A actor lock/gate/role
  -- precede the report. Take the Hangout parent UPDATE lock exactly once,
  -- then retry identity, case, and writes. No FOR SHARE upgrade.
  perform private.social_hangout_mutation_lock();
  actor:=private.moderation_actor();
  normalized_reason:=private.profile_trim(p_reason);
  if p_report_id is null or p_request_id is null or p_expected_case_revision is null
    or p_expected_case_revision<0 or normalized_reason is null
    or char_length(normalized_reason) not between 1 and 2000 then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  select * into r from private.safety_reports where id=p_report_id for share;
  if not found or r.target_type<>'hangout' or r.reporter_id=actor then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  select * into h from public.hangouts where id=r.target_id for update;
  if not found or h.host_id=actor then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  -- Recheck every authority source after the parent wait. The live target
  -- stays locked through commit, so host and campus cannot change beneath us.
  if not exists(select 1 from private.moderation_feature_gate where singleton and enabled)
    or not exists(select 1 from public.accounts where id=actor and status='active')
    or not exists(select 1 from public.platform_roles where user_id=actor
      and role in ('moderator','admin'))
    or r.reporter_id=actor or h.host_id=actor then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  fingerprint:='hangout:'||md5(jsonb_build_array(p_report_id,
    p_expected_case_revision,normalized_reason)::text);
  perform pg_advisory_xact_lock(hashtextextended(actor::text||p_request_id::text,17017));
  select * into prior from private.moderation_requests
    where operator_id=actor and request_id=p_request_id;
  if found then
    if prior.fingerprint<>fingerprint or prior.report_id<>p_report_id
      or not exists(select 1 from private.hangout_disables d
        where d.operator_id=actor and d.request_id=p_request_id
          and d.report_id=p_report_id and d.hangout_id=h.id) then
      raise exception 'Moderation unavailable' using errcode='42501'; end if;
    case_state:=prior.result_state; revision:=prior.result_revision;
    target_disabled:=true; return next; return;
  end if;
  select * into c from private.moderation_cases
    where report_id=p_report_id for update;
  if not found or c.state<>'in_review' or c.revision<>p_expected_case_revision
    or exists(select 1 from private.hangout_disables where hangout_id=h.id) then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  insert into private.hangout_disables(report_id,hangout_id,operator_id,request_id,
    subject_campus_id,reason)
    values(r.id,h.id,actor,p_request_id,h.university_id,normalized_reason)
    returning id into saved_disable;
  update private.moderation_cases set state='closed',revision=c.revision+1,
    note=normalized_reason,disposition='action_taken',duplicate_report_id=null,
    sanction_id=null,hangout_disable_id=saved_disable where report_id=r.id;
  insert into private.moderation_requests(operator_id,request_id,fingerprint,
    report_id,result_state,result_revision)
    values(actor,p_request_id,fingerprint,r.id,'closed',c.revision+1);
  insert into private.moderation_audit(operator_id,action,report_id,
    subject_target_type,subject_target_id,subject_campus_id,request_id,
    previous_state,new_state,previous_revision,new_revision,reason,hangout_disable_id,
    previous_hangout_disabled,new_hangout_disabled)
    values(actor,'disable_hangout',r.id,'hangout',h.id,h.university_id,p_request_id,
      c.state,'closed',c.revision,c.revision+1,normalized_reason,saved_disable,false,true);
  case_state:='closed'; revision:=c.revision+1; target_disabled:=true;
  return next;
end;

declare campus uuid;
declare query_text text := nullif(pg_catalog.btrim(p_search), '');
declare major_text text := nullif(pg_catalog.btrim(p_major), '');
declare cursor_name text;
begin
  perform private.people_require_read_committed();
  if p_limit is null or p_limit not between 1 and 24
    or (p_search is not null and pg_catalog.length(p_search) > 100)
    or (p_major is not null and pg_catalog.length(p_major) > 200)
    or (p_graduation_year is not null and p_graduation_year not between 1900 and 2200)
    or p_after_name is not null then
    raise exception 'Invalid People browse input' using errcode = '22023';
  end if;
  if not private.people_enabled() then
    raise exception 'People operation unavailable' using errcode = '42501';
  end if;
  campus := private.people_ready_campus();
  if campus is null then
    raise exception 'People operation unavailable' using errcode = '42501';
  end if;
  if p_after_id is not null then
    select p.real_name into cursor_name
    from public.profiles p
    join public.university_memberships m on m.user_id = p.user_id and m.university_id = campus
    join public.universities c on c.id = m.university_id
    where p.user_id = p_after_id
      and private.people_visible(p.user_id, campus)
      and (query_text is null or pg_catalog.strpos(pg_catalog.lower(p.real_name), pg_catalog.lower(query_text)) > 0)
      and (p_graduation_year is null or p.graduation_year = p_graduation_year)
      and (major_text is null or pg_catalog.lower(p.major) = pg_catalog.lower(major_text));
    if not found then
      raise exception 'People operation unavailable' using errcode = '42501';
    end if;
    cursor_name := pg_catalog.lower(pg_catalog.btrim(cursor_name));
  end if;
  return query
    select p.user_id, p.real_name, c.name, p.graduation_year, p.major
    from public.profiles p
    join public.university_memberships m on m.user_id = p.user_id and m.university_id = campus
    join public.universities c on c.id = m.university_id
    where private.people_visible(p.user_id, campus)
      and (query_text is null or pg_catalog.strpos(pg_catalog.lower(p.real_name), pg_catalog.lower(query_text)) > 0)
      and (p_graduation_year is null or p.graduation_year = p_graduation_year)
      and (major_text is null or pg_catalog.lower(p.major) = pg_catalog.lower(major_text))
      and (p_after_id is null or
        ((pg_catalog.lower(pg_catalog.btrim(p.real_name)) collate "C"), p.user_id) >
        ((cursor_name collate "C"), p_after_id))
    order by pg_catalog.lower(pg_catalog.btrim(p.real_name)) collate "C", p.user_id
    limit p_limit;
end;

declare h public.hangouts; next_revision bigint;
begin
  perform private.social_hangout_mutation_lock();
 h=private.lock_hangout(p_hangout_id);
 if h.host_id<>auth.uid() or h.status<>'published' then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 perform private.check_hangout_revision(h,p_expected_revision);
 update public.hangouts set status='cancelled',joining_state='closed',revision=revision+1,updated_at=clock_timestamp() where id=h.id returning revision into next_revision;
 perform private.notification_emit_hangout(gen_random_uuid(),h.id,auth.uid(),'hangout_cancelled');
 return next_revision;
end;

declare actor uuid := auth.uid(); normalized text; fingerprint text;
  old_retry private.dm_retries%rowtype; pair private.dm_pairs%rowtype; message_id uuid;
begin
  perform private.social_hangout_mutation_lock();
  perform private.people_require_read_committed();
  if actor is null or p_target_id is null or actor=p_target_id or p_request_id is null
     or p_body is null then raise exception 'DM unavailable' using errcode='42501'; end if;
  normalized := private.profile_trim(p_body);
  if length(normalized) not between 1 and 2000 then
    raise exception 'Invalid DM body' using errcode='22023'; end if;
  fingerprint := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(normalized,'UTF8')),'hex');
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'dm-request:'||actor::text||':'||p_request_id::text,0));
  perform private.friendship_lock_pair(actor,p_target_id);
  perform private.dm_lock_evidence(actor,p_target_id);
  if not private.dm_eligible(p_target_id) then
    raise exception 'DM unavailable' using errcode='42501'; end if;
  select * into old_retry from private.dm_retries r
    where r.actor_id=actor and r.request_id=p_request_id;
  if found then
    if old_retry.kind <> 'create' or old_retry.target_id <> p_target_id
       or old_retry.fingerprint <> fingerprint then
      raise exception 'DM request conflict' using errcode='23505'; end if;
    select * into pair from private.dm_pairs d where d.generation_id=old_retry.generation_id
      and d.state in ('pending','accepted');
    if not found then raise exception 'DM unavailable' using errcode='42501'; end if;
    return pair.generation_id;
  end if;
  if exists(select 1 from private.dm_suppression s
       where s.initiator_id=actor and s.recipient_id=p_target_id)
     or exists(select 1 from private.dm_pairs d
       where d.low_id=least(actor,p_target_id) and d.high_id=greatest(actor,p_target_id)
         and d.state in ('pending','accepted')) then
    raise exception 'DM unavailable' using errcode='42501'; end if;
  insert into private.dm_pairs(low_id,high_id,initiator_id,campus_id,next_sequence)
    values(least(actor,p_target_id),greatest(actor,p_target_id),actor,
      private.people_ready_campus(),2) returning * into pair;
  insert into private.dm_messages(generation_id,sequence,author_id,body)
    values(pair.generation_id,1,actor,normalized) returning id into message_id;
  insert into private.dm_retries(actor_id,request_id,kind,target_id,generation_id,message_id,fingerprint)
    values(actor,p_request_id,'create',p_target_id,pair.generation_id,message_id,fingerprint);
  return pair.generation_id;
end;

declare actor uuid := auth.uid();
declare old_request private.friendship_create_requests%rowtype;
declare existing private.friendships%rowtype;
declare new_generation uuid;
begin
  perform private.social_hangout_mutation_lock();
  perform private.people_require_read_committed();
  if actor is null or p_target_id is null or p_target_id = actor or p_request_id is null
    or not private.friendship_enabled() or not private.people_active_owner() then
    raise exception 'Friendship unavailable' using errcode = '42501';
  end if;
  -- Serialize retries of one creation key before locking the unordered pair.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'friendship-request:' || actor::text || ':' || p_request_id::text, 0));
  perform private.friendship_lock_pair(actor, p_target_id);
  perform private.friendship_lock_eligibility(actor, p_target_id);
  if not private.friendship_enabled() or not private.people_active_owner() then
    raise exception 'Friendship unavailable' using errcode = '42501';
  end if;
  select * into old_request from private.friendship_create_requests r
    where r.actor_id = actor and r.request_id = p_request_id;
  if found then
    if old_request.target_id <> p_target_id then
      raise exception 'Friendship unavailable' using errcode = '42501';
    end if;
    select * into existing from private.friendships f
      where f.low_id = least(actor,p_target_id) and f.high_id = greatest(actor,p_target_id)
        and f.generation_id = old_request.generation_id;
    if not found or not private.friendship_eligible(p_target_id) then
      raise exception 'Friendship unavailable' using errcode = '42501';
    end if;
    return existing.generation_id;
  end if;
  if not private.friendship_eligible(p_target_id)
    or exists(select 1 from private.friendship_suppression s
      where s.requester_id = actor and s.recipient_id = p_target_id)
    or exists(select 1 from private.friendships f
      where f.low_id = least(actor,p_target_id) and f.high_id = greatest(actor,p_target_id)) then
    raise exception 'Friendship unavailable' using errcode = '42501';
  end if;
  new_generation := gen_random_uuid();
  insert into private.friendships(low_id,high_id,requester_id,campus_id,generation_id)
    values(least(actor,p_target_id),greatest(actor,p_target_id),actor,
      private.people_ready_campus(),new_generation);
  insert into private.friendship_create_requests(actor_id,request_id,target_id,generation_id)
    values(actor,p_request_id,p_target_id,new_generation);
  return new_generation;
end;

declare campus uuid; result uuid; existing_id uuid; existing_fingerprint text; fingerprint text; normalized_private text;
begin
  perform private.social_hangout_mutation_lock();
 campus=private.ready_campus();
 if campus is null then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 perform private.validate_hangout_input(p_title,p_starts_at,p_public_place,p_public_latitude,p_public_longitude,p_description,p_ends_at,p_campus_zone,p_visibility,p_location_precision,p_eligibility);
 perform private.validate_hangout_instructions(p_private_instructions);
 if p_request_id is null then raise exception 'Invalid Hangout input' using errcode='22023'; end if;
 normalized_private=nullif(private.profile_trim(p_private_instructions),'');
 fingerprint=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(jsonb_build_array(private.profile_trim(p_title),extract(epoch from p_starts_at),
   private.profile_trim(p_public_place),p_public_latitude,p_public_longitude,
   nullif(private.profile_trim(p_description),''),extract(epoch from p_ends_at),
   nullif(private.profile_trim(p_campus_zone),''),normalized_private,
   p_visibility,p_location_precision,p_eligibility)::text,'UTF8')),'hex');
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(auth.uid()::text||p_request_id::text,0));
 perform 1 from private.hangout_feature_gate where singleton for share;
 perform private.safety_lock_hangout_evidence(auth.uid(),campus);
 if private.ready_campus() is distinct from campus then
   raise exception 'Hangout operation not permitted' using errcode='42501';
 end if;
 select r.hangout_id,r.payload_fingerprint into existing_id,existing_fingerprint
 from private.hangout_create_requests r where r.host_id=auth.uid() and r.request_id=p_request_id;
 if found then
   -- The current gate/readiness/campus and row access must still hold. Never
   -- replay private content, even when the original write had it.
   if not private.can_read_hangout(existing_id) then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
   if existing_fingerprint<>fingerprint then raise exception 'Creation request conflict' using errcode='23505'; end if;
   return existing_id;
 end if;
 if p_starts_at<clock_timestamp() or p_starts_at>clock_timestamp()+interval '366 days' then
   raise exception 'Invalid Hangout input' using errcode='22023';
 end if;
 insert into public.hangouts(university_id,host_id,title,starts_at,public_place,public_latitude,public_longitude,description,ends_at,campus_zone)
 values(campus,auth.uid(),private.profile_trim(p_title),p_starts_at,private.profile_trim(p_public_place),p_public_latitude,p_public_longitude,nullif(private.profile_trim(p_description),''),p_ends_at,nullif(private.profile_trim(p_campus_zone),'')) returning id into result;
 insert into public.hangout_participants(hangout_id,account_id,state) values(result,auth.uid(),'joined');
 if normalized_private is not null then
   insert into public.hangout_private_locations(hangout_id,instructions) values(result,normalized_private);
 end if;
 insert into private.hangout_create_requests(host_id,request_id,hangout_id,payload_fingerprint) values(auth.uid(),p_request_id,result,fingerprint);
 return result;
end;

declare h public.hangouts; next_revision bigint;
begin
  perform private.social_hangout_mutation_lock();
  h := private.lock_hangout(p_hangout_id);
  if h.host_id <> auth.uid() or h.status <> 'published' or p_account_id is null
    or p_account_id = h.host_id or not exists(
      select 1 from private.hangout_cohosts c where c.hangout_id = h.id
        and c.account_id = p_account_id) then
    raise exception 'Hangout operation not permitted' using errcode = '42501';
  end if;
  perform private.check_hangout_revision(h, p_expected_revision);
  delete from private.hangout_cohosts where hangout_id = h.id and account_id = p_account_id;
  update public.hangouts set revision = revision + 1, updated_at = clock_timestamp()
    where id = h.id returning revision into next_revision;
  return next_revision;
end;

declare h public.hangouts; next_revision bigint; normalized_private text; old_private text; material boolean;
begin
  perform private.social_hangout_mutation_lock();
 h=private.lock_hangout(p_hangout_id);
 if (h.host_id<>auth.uid() and not private.effective_hangout_cohost(h.id,auth.uid())) or h.status<>'published' then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 perform private.check_hangout_revision(h,p_expected_revision);
 perform private.validate_hangout_input(p_title,p_starts_at,p_public_place,p_public_latitude,p_public_longitude,p_description,p_ends_at,p_campus_zone,p_visibility,p_location_precision,p_eligibility);
 perform private.validate_hangout_instructions(p_private_instructions);
 if p_starts_at is distinct from h.starts_at and (p_starts_at<clock_timestamp() or p_starts_at>clock_timestamp()+interval '366 days') then
   raise exception 'Invalid Hangout input' using errcode='22023'; end if;
 normalized_private=nullif(private.profile_trim(p_private_instructions),'');
 select instructions into old_private from public.hangout_private_locations where hangout_id=h.id;
 update public.hangouts set title=private.profile_trim(p_title),starts_at=p_starts_at,public_place=private.profile_trim(p_public_place),public_latitude=p_public_latitude,public_longitude=p_public_longitude,description=nullif(private.profile_trim(p_description),''),ends_at=p_ends_at,campus_zone=nullif(private.profile_trim(p_campus_zone),''),revision=revision+1,updated_at=clock_timestamp() where id=h.id returning revision into next_revision;
 if normalized_private is null then delete from public.hangout_private_locations where hangout_id=h.id;
 else insert into public.hangout_private_locations(hangout_id,instructions) values(h.id,normalized_private)
  on conflict(hangout_id) do update set instructions=excluded.instructions,updated_at=clock_timestamp(); end if;
 material:=row(h.title,h.starts_at,h.public_place,h.public_latitude,h.public_longitude,h.description,h.ends_at,h.campus_zone,old_private)
  is distinct from row(private.profile_trim(p_title),p_starts_at,private.profile_trim(p_public_place),p_public_latitude,p_public_longitude,
   nullif(private.profile_trim(p_description),''),p_ends_at,nullif(private.profile_trim(p_campus_zone),''),normalized_private);
 if material then perform private.notification_emit_hangout(gen_random_uuid(),h.id,auth.uid(),'hangout_edited'); end if;
 return next_revision;
end;

declare actor uuid := auth.uid();
begin
  perform private.people_require_read_committed();
  if actor is null or not private.friendship_enabled() or not private.people_active_owner() then
    raise exception 'Friendship unavailable' using errcode = '42501';
  end if;
  return query select p_peer_id,f.generation_id,
    case when f.requester_id = actor then 'outgoing' else 'incoming' end,f.state
    from private.friendships f
    where p_peer_id is not null and f.low_id = least(actor,p_peer_id)
      and f.high_id = greatest(actor,p_peer_id);
end;

declare h public.hangouts; gate_enabled boolean;
begin
  if auth.uid() is null or p_hangout_id is null
    or current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'Hangout size unavailable' using errcode = '42501';
  end if;
  select * into h from public.hangouts where id = p_hangout_id for share;
  if not found then raise exception 'Hangout size unavailable' using errcode = '42501'; end if;
  perform 1 from private.hangout_feature_gate where singleton for share;
  select enabled into gate_enabled from private.large_hangout_feature_gate
    where singleton for share;
  if not gate_enabled or not private.hangouts_enabled()
    or h.host_id <> auth.uid() or h.status <> 'published'
    or h.visibility <> 'campus' or h.university_id is distinct from private.ready_campus()
    or not private.can_read_hangout(h.id) then
    raise exception 'Hangout size unavailable' using errcode = '42501';
  end if;
  return query select (count(*) >= 25) from public.hangout_participants p
    where p.hangout_id = h.id and p.state = 'joined';
end;

declare h public.hangouts;
begin
 if p_account_id=auth.uid() and
   ((private.safety_enabled() and private.people_active_owner())
     or private.can_read_hangout(p_hangout_id)) then
   return (select p.state from public.hangout_participants p
     where p.hangout_id=p_hangout_id and p.account_id=auth.uid());
 end if;
 if private.ready_campus() is null then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 select * into h from public.hangouts where id=p_hangout_id;
 if not found or not private.can_read_hangout(h.id) or h.host_id<>auth.uid() then
   raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 if p_account_id is null or private.safety_pair_blocked(auth.uid(),p_account_id) then
   return null;
 end if;
 return (select state from public.hangout_participants
   where hangout_id=h.id and account_id=p_account_id);
end;

declare actor uuid; r private.safety_reports%rowtype;
begin
  actor:=private.moderation_actor();
  if p_report_id is null or not private.moderation_report_allowed(actor,p_report_id) then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  select * into r from private.safety_reports where id=p_report_id;
  report_id:=r.id; submitted_at:=r.submitted_at; target_type:=r.target_type;
  target_id:=r.target_id; reporter_id:=r.reporter_id; category:=r.category;
  narrative:=r.narrative; provenance_kind:=r.provenance_kind;
  provenance_ref_id:=r.provenance_ref_id;
  select coalesce(c.state,'open'),coalesce(c.revision,0),c.note,c.disposition
    into case_state,case_revision,case_note,disposition
    from (select 1) x left join private.moderation_cases c on c.report_id=r.id;
  if r.target_type='user' then
    select a.status,m.university_id into target_status,target_campus_id
      from public.accounts a left join public.university_memberships m on m.user_id=a.id
      where a.id=r.target_id;
    target_disabled:=null;
  else
    select h.status,h.university_id,
      exists(select 1 from private.hangout_disables d where d.hangout_id=h.id)
      into target_status,target_campus_id,target_disabled
      from public.hangouts h where h.id=r.target_id;
  end if;
  target_status:=coalesce(target_status,'unavailable');
  insert into private.moderation_audit(operator_id,action,report_id,request_id)
    values(actor,'detail_read',r.id,gen_random_uuid());
  return next;
end;

declare owner_id uuid;
begin
 owner_id:=private.notification_require_owner();
 return query select c.category,coalesce(p.enabled,true) from
 (values('social_requests'),('messages'),('hangout_updates'),('host_activity')) c(category)
 left join private.notification_preferences p on p.recipient_id=owner_id and p.category=c.category
 order by c.category;
end;

declare campus uuid;
begin
  perform private.people_require_read_committed();
  if not private.people_enabled() then
    raise exception 'People operation unavailable' using errcode = '42501';
  end if;
  campus := private.people_ready_campus();
  if campus is null then
    raise exception 'People operation unavailable' using errcode = '42501';
  end if;
  return query
    select p.user_id, p.real_name, c.name, p.graduation_year, p.major,
      p.bio, p.interests, p.down_to_do
    from public.profiles p
    join public.university_memberships m on m.user_id = p.user_id and m.university_id = campus
    join public.universities c on c.id = m.university_id
    where p.user_id = p_account_id and private.people_visible(p.user_id, campus);
end;

begin
  perform private.people_require_read_committed();
  if not private.people_active_owner() then
    raise exception 'People operation unavailable' using errcode = '42501';
  end if;
  return coalesce((select v.opted_in from private.people_preferences v
    where v.account_id = (select auth.uid())), false);
end;

declare h public.hangouts; participant_state text; did_join boolean;
begin
  perform private.social_hangout_mutation_lock();
  h = private.lock_hangout(p_hangout_id);
  if h.status <> 'published' or h.joining_state <> 'open' then
    raise exception 'Hangout operation not permitted' using errcode = '42501';
  end if;
  if exists(select 1 from public.hangout_participants p where p.hangout_id = h.id
    and p.state = 'joined' and p.account_id <> auth.uid()
    and private.safety_pair_blocked(auth.uid(), p.account_id)) then
    raise exception 'Hangout operation not permitted' using errcode = '42501';
  end if;
  select state into participant_state from public.hangout_participants
    where hangout_id = h.id and account_id = auth.uid();
  if participant_state = 'removed' then
    raise exception 'Hangout operation not permitted' using errcode = '42501';
  end if;
  if participant_state = 'joined' then return; end if;
  insert into public.hangout_participants(hangout_id, account_id, state)
    values (h.id, auth.uid(), 'joined')
    on conflict(hangout_id, account_id) do update
      set state = 'joined', joined_at = clock_timestamp(), left_at = null,
          updated_at = clock_timestamp()
      where hangout_participants.state = 'left';
  did_join := found;
  if did_join then
    perform private.safety_record_joined_overlap(h.id, auth.uid());
    perform private.record_large_hangout_join(h.id);
    perform private.notification_emit_hangout(gen_random_uuid(), h.id, auth.uid(), 'hangout_joined');
  end if;
end;

declare h public.hangouts; was_cohost boolean;
begin
  perform private.social_hangout_mutation_lock();
 h=private.lock_hangout(p_hangout_id);
 if h.host_id=auth.uid() then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 was_cohost:=exists(select 1 from private.hangout_cohosts c where c.hangout_id=h.id and c.account_id=auth.uid());
 perform private.safety_record_joined_overlap(h.id,auth.uid());
 update public.hangout_participants set state='left',left_at=clock_timestamp(),updated_at=clock_timestamp()
 where hangout_id=h.id and account_id=auth.uid() and state='joined';
 if not found then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 if was_cohost then
   update public.hangouts set revision=revision+1,
     updated_at=case when status='cancelled' then updated_at else clock_timestamp() end
     where id=h.id;
 end if;
 perform private.notification_emit_hangout(gen_random_uuid(),h.id,auth.uid(),'hangout_left');
end;

declare actor uuid := auth.uid();
begin
  perform private.people_require_read_committed();
  if p_limit is null or p_limit not between 1 and 24 then
    raise exception 'Invalid friendship page size' using errcode = '22023';
  end if;
  if actor is null or not private.friendship_enabled() or not private.people_active_owner() then
    raise exception 'Friendship unavailable' using errcode = '42501';
  end if;
  return query select case when f.low_id = actor then f.high_id else f.low_id end,
    f.generation_id,
    case when f.requester_id = actor then 'outgoing' else 'incoming' end,
    f.state
  from private.friendships f where (f.low_id = actor or f.high_id = actor)
    and (p_after_peer_id is null or
      (case when f.low_id = actor then f.high_id else f.low_id end) > p_after_peer_id)
  order by 1 limit p_limit;
end;

declare h public.hangouts;
begin
  if auth.uid() is null or p_hangout_id is null or p_limit is null
    or p_limit not between 1 and 24
    or current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'Hangout operation not permitted' using errcode = '42501';
  end if;
  select * into h from public.hangouts where id = p_hangout_id for share;
  if not found then raise exception 'Hangout operation not permitted' using errcode = '42501'; end if;
  perform 1 from private.hangout_feature_gate where singleton for share;
  perform private.safety_lock_hangout_evidence(auth.uid(), h.university_id);
  if h.host_id <> auth.uid() or h.status <> 'published'
    or h.university_id is distinct from private.ready_campus()
    or not private.can_read_hangout(h.id) then
    raise exception 'Hangout operation not permitted' using errcode = '42501';
  end if;
  return query select c.account_id from private.hangout_cohosts c
    where c.hangout_id = h.id
      and (p_after_account_id is null or c.account_id > p_after_account_id)
    order by c.account_id limit p_limit;
end;

declare h public.hangouts;
begin
  if auth.uid() is null or p_hangout_id is null or p_limit is null
    or p_limit not between 1 and 24
    or current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'Hangout operation not permitted' using errcode = '42501';
  end if;
  select * into h from public.hangouts where id = p_hangout_id for share;
  if not found then raise exception 'Hangout operation not permitted' using errcode = '42501'; end if;
  perform 1 from private.hangout_feature_gate where singleton for share;
  perform private.safety_lock_hangout_evidence(auth.uid(), h.university_id);
  if not private.can_read_hangout(h.id) or h.status <> 'published' then
    raise exception 'Hangout operation not permitted' using errcode = '42501';
  end if;
  return query select p.account_id,
    case when p.account_id = h.host_id then 'host'
      when private.effective_hangout_cohost(h.id,p.account_id) then 'cohost'
      else 'participant' end
    from public.hangout_participants p where p.hangout_id = h.id
      and (p_after_account_id is null or p.account_id > p_after_account_id)
      and private.can_read_hangout_roster(h.id,p.account_id)
    order by p.account_id limit p_limit;
end;

declare actor uuid; r private.safety_reports%rowtype; ids uuid[]:=array[]::uuid[]; n integer:=0;
begin
  actor:=private.moderation_actor();
  if p_limit is null or p_limit<1 or p_limit>24
    or (p_after_submitted_at is null)<>(p_after_id is null) then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  for r in select * from private.safety_reports s
    where p_after_id is null or (s.submitted_at,s.id)<(p_after_submitted_at,p_after_id)
    order by s.submitted_at desc,s.id desc loop
    if private.moderation_report_allowed(actor,r.id) then
      report_id:=r.id; submitted_at:=r.submitted_at; target_type:=r.target_type;
      target_id:=r.target_id; reporter_id:=r.reporter_id; category:=r.category;
      select coalesce(c.state,'open') into case_state from (select 1) x
        left join private.moderation_cases c on c.report_id=r.id;
      ids:=array_append(ids,r.id); n:=n+1;
      return next;
      exit when n>=p_limit;
    end if;
  end loop;
  -- The gate and live actor remain locked; recheck after potential row waits.
  if not exists(select 1 from private.moderation_feature_gate where enabled)
    or not exists(select 1 from public.accounts where id=actor and status='active')
    or not exists(select 1 from public.platform_roles where user_id=actor and role in ('moderator','admin')) then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  insert into private.moderation_audit(operator_id,action,request_id,page_report_ids,page_count)
    values(actor,'queue_read',gen_random_uuid(),ids,n);
end;

begin
  perform private.people_require_read_committed();
  if not private.safety_enabled() or not private.people_active_owner() then
    raise exception 'Safety operation unavailable' using errcode='42501'; end if;
  if p_limit is null or p_limit not between 1 and 24 then
    raise exception 'Invalid safety page' using errcode='22023'; end if;
  return query select p.hangout_id,p.state from public.hangout_participants p
    where p.account_id=auth.uid() and (p_after_id is null or p.hangout_id>p_after_id)
    order by p.hangout_id limit p_limit;
end;

begin
  perform private.people_require_read_committed();
  if not private.safety_enabled() or not private.people_active_owner() then
    raise exception 'Safety operation unavailable' using errcode='42501'; end if;
  if p_limit is null or p_limit not between 1 and 24 then
    raise exception 'Invalid safety page' using errcode='22023'; end if;
  return query select b.blocked_id from private.people_blocks b
    where b.blocker_id=auth.uid() and (p_after_id is null or b.blocked_id>p_after_id)
    order by b.blocked_id limit p_limit;
end;

