 if not private.notification_enabled() or not private.people_active_owner() then
  raise exception 'Notifications unavailable' using errcode='42501';end if;
 update private.notification_items n set read_at=coalesce(n.read_at,clock_timestamp())
  where n.id=p_notification_id and n.recipient_id=owner_id;
 return found;
end;

declare h public.hangouts; next_revision bigint;
begin
  perform private.social_hangout_mutation_lock();
  h := private.lock_hangout(p_hangout_id);
  if p_account_id is not null and p_account_id <> h.host_id then
    perform private.safety_lock_hangout_evidence(p_account_id, h.university_id);
  end if;
  if h.host_id <> auth.uid() or h.status <> 'published' or p_account_id is null
    or p_account_id = h.host_id or not exists(
      select 1 from public.hangout_participants p where p.hangout_id = h.id
        and p.account_id = p_account_id and p.state = 'joined')
    or not private.ready_subject_campus(p_account_id, h.university_id)
    or private.safety_pair_blocked(h.host_id, p_account_id)
    or exists(select 1 from private.hangout_cohosts c where c.hangout_id = h.id
      and c.account_id = p_account_id) then
    raise exception 'Hangout operation not permitted' using errcode = '42501';
  end if;
  perform private.check_hangout_revision(h, p_expected_revision);
  insert into private.hangout_cohosts(hangout_id, account_id) values(h.id, p_account_id);
  update public.hangouts set revision = revision + 1, updated_at = clock_timestamp()
    where id = h.id returning revision into next_revision;
  return next_revision;
end;

declare gate_enabled boolean; gate_epoch uuid; campus uuid; result jsonb;
begin
  if auth.uid() is null or current_setting('transaction_isolation') <> 'read committed'
    or p_west is null or p_south is null or p_east is null or p_north is null
    or p_west < -79.13 or p_east > -78.98 or p_south < 35.85 or p_north > 35.97
    or not (p_west < p_east and p_south < p_north)
    or p_time_filter not in ('upcoming', 'all') or p_time_filter is null
    or p_joining_filter not in ('any', 'open') or p_joining_filter is null
    or p_cutoff is null or not isfinite(p_cutoff)
    or abs(extract(epoch from (clock_timestamp() - p_cutoff))) > 120 then
    raise exception 'Saved Hangouts unavailable' using errcode = '42501';
  end if;
  perform 1 from private.hangout_feature_gate where singleton for share;
  campus := private.ready_campus();
  if campus is null then raise exception 'Saved Hangouts unavailable' using errcode = '42501'; end if;
  select enabled, ranking_epoch into gate_enabled, gate_epoch
    from private.large_hangout_feature_gate where singleton for share;
  if gate_epoch is null or not private.hangouts_enabled() then
    raise exception 'Saved Hangouts unavailable' using errcode = '42501';
  end if;
  with candidates as materialized (
    select h.id, h.title, h.description, h.starts_at, h.ends_at,
      h.public_place, h.public_latitude, h.public_longitude,
      h.campus_zone, h.joining_state
    from public.hangouts h
    where h.university_id = campus and h.status = 'published' and h.visibility = 'campus'
      and h.public_longitude between p_west and p_east
      and h.public_latitude between p_south and p_north
      and (p_time_filter = 'all' or h.starts_at >= p_cutoff)
      and (p_joining_filter = 'any' or h.joining_state = 'open')
      and private.can_read_hangout(h.id)
  ), ranked as (
    select c.*, case when gate_enabled then (
      select count(*) >= 25 from public.hangout_participants p
      where p.hangout_id = c.id and p.state = 'joined'
        and private.can_read_hangout_roster(c.id, p.account_id)
    ) else false end as visible_large
    from candidates c
  ), probe as (
    select * from ranked order by visible_large, starts_at, id limit 101
  ), ordered as (
    select row_number() over (order by visible_large, starts_at, id) as ordinal,
      jsonb_build_object(
        'id', id, 'title', title, 'description', description,
        'starts_at', starts_at, 'ends_at', ends_at,
        'public_place', public_place, 'public_latitude', public_latitude,
        'public_longitude', public_longitude, 'campus_zone', campus_zone,
        'joining_state', joining_state) as pin from probe
  )
  select jsonb_build_object('pins', coalesce(jsonb_agg(pin order by ordinal), '[]'::jsonb),
    'epoch', gate_epoch,
    'ranking_mode', case when gate_enabled then 'small_first' else 'chronological' end)
    into result from ordered;
  return result;
end;

declare h public.hangouts; next_revision bigint; target_state text;
begin
  perform private.social_hangout_mutation_lock();
  h := private.lock_hangout(p_hangout_id);
  if p_account_id is null or p_account_id = h.host_id
    or (h.host_id <> auth.uid() and not private.effective_hangout_cohost(h.id, auth.uid()))
    or (h.host_id <> auth.uid() and h.status <> 'published') then
    raise exception 'Hangout operation not permitted' using errcode = '42501';
  end if;
  perform private.check_hangout_revision(h, p_expected_revision);
  select state into target_state from public.hangout_participants p
    where p.hangout_id = h.id and p.account_id = p_account_id;
  if target_state not in ('joined','left') or target_state is null then
    raise exception 'Hangout operation not permitted' using errcode = '42501';
  end if;
  if h.host_id <> auth.uid() then
    perform private.safety_lock_hangout_evidence(p_account_id, h.university_id);
    if target_state <> 'joined'
      or not private.ready_subject_campus(p_account_id, h.university_id)
      or exists(select 1 from private.hangout_cohosts c
        where c.hangout_id = h.id and c.account_id = p_account_id)
      or private.safety_pair_blocked(auth.uid(), p_account_id)
      or not private.effective_hangout_cohost(h.id, auth.uid()) then
      raise exception 'Hangout operation not permitted' using errcode = '42501';
    end if;
  end if;
  perform private.safety_record_joined_overlap(h.id, p_account_id);
  update public.hangout_participants set state = 'removed',
    removed_at = clock_timestamp(), updated_at = clock_timestamp()
    where hangout_id = h.id and account_id = p_account_id and state in ('joined','left');
  if not found then raise exception 'Hangout operation not permitted' using errcode = '42501'; end if;
  update public.hangouts set revision = revision + 1,
    updated_at = case when status = 'cancelled' then updated_at else clock_timestamp() end
    where id = h.id returning revision into next_revision;
  return next_revision;
end;

declare actor uuid := auth.uid(); normalized text; fingerprint text;
  pair private.dm_pairs%rowtype; old_retry private.dm_retries%rowtype; message_id uuid;
begin
  perform private.social_hangout_mutation_lock();
  perform private.people_require_read_committed();
  if actor is null or p_peer_id is null or p_peer_id=actor or p_generation_id is null
     or p_request_id is null or p_body is null then
    raise exception 'DM unavailable' using errcode='42501'; end if;
  normalized := private.profile_trim(p_body);
  if length(normalized) not between 1 and 2000 then
    raise exception 'Invalid DM body' using errcode='22023'; end if;
  fingerprint := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(normalized,'UTF8')),'hex');
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'dm-request:'||actor::text||':'||p_request_id::text,0));
  perform private.friendship_lock_pair(actor,p_peer_id);
  perform private.dm_lock_evidence(actor,p_peer_id);
  if not private.dm_eligible(p_peer_id) then
    raise exception 'DM unavailable' using errcode='42501'; end if;
  select * into pair from private.dm_pairs d where d.generation_id=p_generation_id
    and d.low_id=least(actor,p_peer_id) and d.high_id=greatest(actor,p_peer_id)
    and d.state='accepted';
  if not found then
    raise exception 'DM unavailable' using errcode='42501'; end if;
  select * into old_retry from private.dm_retries r where r.actor_id=actor and r.request_id=p_request_id;
  if found then
    if old_retry.kind <> 'send' or old_retry.target_id <> p_peer_id
      or old_retry.generation_id <> p_generation_id or old_retry.fingerprint <> fingerprint then
      raise exception 'DM request conflict' using errcode='23505'; end if;
    return old_retry.message_id;
  end if;
  insert into private.dm_messages(generation_id,sequence,author_id,body)
    values(pair.generation_id,pair.next_sequence,actor,normalized) returning id into message_id;
  update private.dm_pairs d set next_sequence=next_sequence+1 where d.generation_id=pair.generation_id;
  insert into private.dm_retries(actor_id,request_id,kind,target_id,generation_id,message_id,fingerprint)
    values(actor,p_request_id,'send',p_peer_id,pair.generation_id,message_id,fingerprint);
  return message_id;
end;

declare actor uuid := auth.uid(); h public.hangouts; normalized text;
  fingerprint text; old_message uuid; old_fingerprint text; conversation uuid;
  new_sequence bigint; new_message uuid;
begin
  perform private.social_hangout_mutation_lock();
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'Hangout chat unavailable' using errcode = '42501';
  end if;
  -- Serialize with join, leave, remove and cancel using their existing parent
  -- lock. This also makes two sends of the same key strictly ordered.
  h := private.lock_hangout(p_hangout_id);
  perform private.chat_lock_evidence(h.id, actor, h.university_id);
  -- A fresh READ COMMITTED statement after lock waits sees committed revocation.
  perform private.chat_require(h.id);
  if p_request_id is null or p_body is null then
    raise exception 'Invalid Hangout message' using errcode = '22023';
  end if;
  normalized := private.profile_trim(p_body);
  if length(normalized) not between 1 and 2000 then
    raise exception 'Invalid Hangout message' using errcode = '22023';
  end if;
  fingerprint := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(normalized, 'UTF8')), 'hex');
  select r.message_id, r.payload_fingerprint into old_message, old_fingerprint
    from private.hangout_message_requests r
    where r.hangout_id = h.id and r.author_id = actor and r.request_id = p_request_id;
  if found then
    if old_fingerprint <> fingerprint then
      raise exception 'Message request conflict' using errcode = '23505';
    end if;
    return query select m.id, m.sequence, m.body, m.created_at, true, actor, null::text
      from private.hangout_messages m where m.id = old_message;
    return;
  end if;
  insert into private.hangout_conversations(hangout_id) values (h.id)
    on conflict(hangout_id) do nothing;
  update private.hangout_conversations c set next_sequence = c.next_sequence + 1
    where c.hangout_id = h.id returning c.id, c.next_sequence - 1 into conversation, new_sequence;
  insert into private.hangout_messages(conversation_id, author_id, sequence, body)
    values (conversation, actor, new_sequence, normalized) returning id into new_message;
  insert into private.hangout_message_requests(hangout_id, author_id, request_id, message_id, payload_fingerprint)
    values (h.id, actor, p_request_id, new_message, fingerprint);
  return query select m.id, m.sequence, m.body, m.created_at, true, actor, null::text
    from private.hangout_messages m where m.id = new_message;
end;

