declare actor uuid:=auth.uid(); reason text:=private.profile_trim(p_reason); prior private.pilot_management_requests%rowtype;
 old private.pilot_account_admission%rowtype; fingerprint jsonb; saved_audit uuid;
begin
 perform private.pilot_lock_management(actor,p_account_id,null);
 perform private.pilot_require_manager();
 if p_account_id is null or p_state is null or p_state not in ('active','revoked') or p_expected_revision is null or p_expected_revision<0
  or p_request_id is null or reason is null or char_length(reason) not between 1 and 2000 then raise exception 'Pilot management unavailable' using errcode='42501'; end if;
 fingerprint:=jsonb_build_array('admission',p_account_id,p_state,p_expected_revision,reason);
 select * into prior from private.pilot_management_requests where actor_id=actor and request_id=p_request_id;
 if found then
  if prior.fingerprint<>fingerprint then raise exception 'Pilot management unavailable' using errcode='42501'; end if;
  perform private.pilot_require_manager(); state:=prior.result_value#>>'{}'; revision:=prior.result_revision; return next; return;
 end if;
 if not exists(select 1 from public.accounts where id=p_account_id) then raise exception 'Pilot management unavailable' using errcode='42501'; end if;
 if p_state='active' then perform private.pilot_require_activation(p_account_id); end if;
 perform private.pilot_require_manager();
 select * into old from private.pilot_account_admission where account_id=p_account_id;
 if coalesce(old.revision,0)<>p_expected_revision then raise exception 'Pilot management unavailable' using errcode='42501'; end if;
 state:=p_state; revision:=case when old.state=p_state then old.revision else coalesce(old.revision,0)+1 end;
 if old.account_id is null then insert into private.pilot_account_admission(account_id,state,revision) values(p_account_id,p_state,revision);
 elsif old.state<>p_state then update private.pilot_account_admission set state=p_state,revision=set_pilot_account_admission.revision,updated_at=clock_timestamp() where account_id=p_account_id; end if;
 insert into private.pilot_management_audit(actor_id,operation,target_id,previous_value,new_value,previous_revision,new_revision,reason,request_id)
 values(actor,'admission',p_account_id,to_jsonb(old.state),to_jsonb(p_state),coalesce(old.revision,0),revision,reason,p_request_id) returning id into saved_audit;
 insert into private.pilot_management_requests values(actor,p_request_id,fingerprint,to_jsonb(p_state),revision,saved_audit);
 return next;
end;

declare actor uuid:=auth.uid(); reason text:=private.profile_trim(p_reason); prior private.pilot_management_requests%rowtype;
 old_value boolean; old_revision bigint; fingerprint jsonb; saved_audit uuid;
begin
 perform private.pilot_lock_management(actor,null,p_key); perform private.pilot_require_manager();
 if p_key is null or p_key not in ('availability','onboarding','hangouts','hangout_chat','calendar','people','friendship','dm','notifications','attendance','optional_profile','extra_photos','analytics','large_hangout_safeguards') or p_enabled is null or p_expected_revision is null or p_expected_revision<0 or p_request_id is null
  or reason is null or char_length(reason) not between 1 and 2000 then raise exception 'Pilot management unavailable' using errcode='42501'; end if;
 if not exists(select 1 from private.pilot_availability where singleton)
  or (p_key<>'availability' and not exists(select 1 from private.pilot_capabilities where key=p_key)) then raise exception 'Pilot management unavailable' using errcode='42501'; end if;
 fingerprint:=jsonb_build_array('policy',p_key,p_enabled,p_expected_revision,reason);
 select * into prior from private.pilot_management_requests where actor_id=actor and request_id=p_request_id;
 if found then
  if prior.fingerprint<>fingerprint then raise exception 'Pilot management unavailable' using errcode='42501'; end if;
  perform private.pilot_require_manager(); enabled:=(prior.result_value#>>'{}')::boolean; revision:=prior.result_revision; return next; return;
 end if;
 if p_key='availability' then select a.enabled,a.revision into old_value,old_revision from private.pilot_availability a where singleton;
 else select c.enabled,c.revision into old_value,old_revision from private.pilot_capabilities c where key=p_key; end if;
 if old_revision is null or old_revision<>p_expected_revision then raise exception 'Pilot management unavailable' using errcode='42501'; end if;
 perform private.pilot_require_manager(); enabled:=p_enabled; revision:=old_revision+case when old_value=p_enabled then 0 else 1 end;
 if old_value<>p_enabled then
  if p_key='availability' then update private.pilot_availability set enabled=p_enabled,revision=set_pilot_policy.revision,updated_at=clock_timestamp() where singleton;
  else update private.pilot_capabilities set enabled=p_enabled,revision=set_pilot_policy.revision,updated_at=clock_timestamp() where key=p_key; end if;
 end if;
 insert into private.pilot_management_audit(actor_id,operation,policy_key,previous_value,new_value,previous_revision,new_revision,reason,request_id)
 values(actor,'policy',p_key,to_jsonb(old_value),to_jsonb(p_enabled),old_revision,revision,reason,p_request_id) returning id into saved_audit;
 insert into private.pilot_management_requests values(actor,p_request_id,fingerprint,to_jsonb(p_enabled),revision,saved_audit); return next;
end;

declare actor uuid:=auth.uid(); target uuid; hangout_row public.hangouts%rowtype; effect text;
begin
  perform private.social_hangout_mutation_lock();
  if actor is null or p_account_id is null or p_account_id=actor or p_blocked is null
      or not private.people_active_owner() then
    raise exception 'Safety operation unavailable' using errcode='42501';
  end if;
  perform private.friendship_lock_pair(actor,p_account_id);
  -- A fresh READ COMMITTED statement discovers the full currently shared set
  -- after every preceding mutation. Sorted parents precede gate/evidence rows.
  for target in
    select x.hangout_id from public.hangout_participants x
    join public.hangout_participants y on y.hangout_id=x.hangout_id
    where x.account_id=actor and y.account_id=p_account_id
      and x.state='joined' and y.state='joined' order by x.hangout_id
  loop
    perform 1 from public.hangouts where id=target for update;
  end loop;
  perform 1 from private.safety_feature_gate where singleton for share;
  if not private.safety_enabled() or not private.people_active_owner() then
    raise exception 'Safety operation unavailable' using errcode='42501';
  end if;
  perform 1 from public.accounts where id=actor for share;
  if not private.people_active_owner() then
    raise exception 'Safety operation unavailable' using errcode='42501'; end if;
  if p_blocked then
    if not private.safety_peer_evidence(actor,p_account_id) then
      perform private.safety_lock_visible_evidence(actor,p_account_id);
    end if;
    if not (private.safety_peer_evidence(actor,p_account_id)
      or (private.pilot_capability_enabled('people') and private.people_enabled() and private.people_ready_campus() is not null
         and private.people_visible(p_account_id,private.people_ready_campus()))) then
      raise exception 'Safety operation unavailable' using errcode='42501';
    end if;
    insert into private.people_blocks(blocker_id,blocked_id)
      values(actor,p_account_id) on conflict do nothing;
    -- Recheck the entire affected set after lock waits. The shared lock keeps
    -- membership stable through commit; this also repairs old-block retries.
    for hangout_row in select hh.* from public.hangouts hh
      join public.hangout_participants x on x.hangout_id=hh.id
        and x.account_id=actor and x.state='joined'
      join public.hangout_participants y on y.hangout_id=hh.id
        and y.account_id=p_account_id and y.state='joined'
      order by hh.id
    loop
      perform private.safety_record_joined_overlap(hangout_row.id,actor);
      perform private.safety_record_joined_overlap(hangout_row.id,p_account_id);
      effect:=case when hangout_row.host_id=actor then 'removed' else 'left' end;
      update public.hangout_participants set state=effect,
        left_at=case when effect='left' then clock_timestamp() else left_at end,
        removed_at=case when effect='removed' then clock_timestamp() else removed_at end,
        updated_at=clock_timestamp()
      where hangout_id=hangout_row.id and account_id=case when effect='removed' then p_account_id else actor end
        and state='joined';
    end loop;
    delete from private.friendships f where f.low_id=least(actor,p_account_id)
      and f.high_id=greatest(actor,p_account_id);
    update private.dm_pairs d set state='blocked' where d.low_id=least(actor,p_account_id)
      and d.high_id=greatest(actor,p_account_id) and d.state in('pending','accepted');
  else
    delete from private.people_blocks b where b.blocker_id=actor and b.blocked_id=p_account_id;
  end if;
  return p_blocked;
end;

declare h public.hangouts; next_revision bigint;
begin
  perform private.social_hangout_mutation_lock();
  h := private.lock_hangout(p_hangout_id);
  if h.status <> 'published' or not private.effective_hangout_cohost(h.id, auth.uid()) then
    raise exception 'Hangout operation not permitted' using errcode = '42501';
  end if;
  perform private.check_hangout_revision(h, p_expected_revision);
  delete from private.hangout_cohosts where hangout_id = h.id and account_id = auth.uid();
  update public.hangouts set revision = revision + 1, updated_at = clock_timestamp()
    where id = h.id returning revision into next_revision;
  return next_revision;
end;

declare
  actor uuid:=auth.uid(); normalized_category text; normalized_narrative text;
  input_fingerprint text; prior private.safety_report_requests%rowtype;
  retained boolean; target_type text; resolved_target uuid;
  provenance text; provenance_ref uuid; campus uuid;
  parent public.hangouts%rowtype; saved_id uuid; saved_at timestamptz;
begin
  perform private.social_hangout_mutation_lock();
  -- Shape validation never probes the target. Invalid UUID text is rejected by
  -- PostgREST before this function with its ordinary parameter error.
  normalized_category:=pg_catalog.lower(private.profile_trim(p_category));
  normalized_narrative:=nullif(private.profile_trim(p_narrative),'');
  if actor is null or p_request_id is null or p_target_id is null
    or p_target_mode is null or p_target_mode not in ('user','hangout','hangout_host')
    or normalized_category is null or normalized_category not in
      ('harassment','safety concern','impersonation','spam/commercial promotion','other')
    or (normalized_narrative is not null and pg_catalog.length(normalized_narrative)>2000)
    or (normalized_category='other' and normalized_narrative is null) then
    raise exception 'Safety report unavailable' using errcode='42501';
  end if;
  input_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_target_mode,p_target_id,normalized_category,normalized_narrative)::text);

  -- The shared transaction lock serializes every caller, including retries.
  -- A replay only reads its own ledger and never resolves its target again.
  select * into prior from private.safety_report_requests r
    where r.reporter_id=actor and r.request_id=p_request_id;
  if found then
    perform 1 from private.safety_feature_gate where singleton for share;
    perform 1 from public.accounts where id=actor for share;
    if not private.safety_enabled() or not private.people_active_owner() then
      raise exception 'Safety report unavailable' using errcode='42501'; end if;
    if prior.input_fingerprint<>input_fingerprint then
      raise exception 'Safety report unavailable' using errcode='42501'; end if;
    return query select r.id,r.submitted_at from private.safety_reports r
      where r.id=prior.report_id and r.reporter_id=actor;
    return;
  end if;

  -- A nonlocking hint chooses the path before any lower gate/account lock.
  -- Its authority is checked again after those locks are held.
  if p_target_mode='user' then
    retained:=private.safety_peer_evidence(actor,p_target_id);
  else
    retained:=exists(select 1 from public.hangout_participants p
      where p.hangout_id=p_target_id and p.account_id=actor);
  end if;
  if not retained then
    if p_target_mode='hangout_host' then
      raise exception 'Safety report unavailable' using errcode='42501';
    elsif p_target_mode='user' then
      perform private.friendship_lock_pair(actor,p_target_id);
    else
      select * into parent from public.hangouts h where h.id=p_target_id for update;
      if not found then raise exception 'Safety report unavailable' using errcode='42501'; end if;
    end if;
  end if;

  perform 1 from private.safety_feature_gate where singleton for share;
  if not retained then
    if p_target_mode='user' then
      perform private.safety_lock_visible_evidence(actor,p_target_id);
    else
      perform 1 from private.hangout_feature_gate where singleton for share;
      perform private.safety_lock_hangout_evidence(actor,parent.university_id);
    end if;
  else
    perform 1 from public.accounts where id=actor for share;
  end if;

  -- Each of these checks is a fresh READ COMMITTED statement after all waits.
  if not private.safety_enabled() or not private.people_active_owner() then
    raise exception 'Safety report unavailable' using errcode='42501'; end if;
  if retained then
    if p_target_mode='user' then
      select kind,ref_id into provenance,provenance_ref
        from private.safety_report_peer_source(actor,p_target_id);
      if not found or not private.safety_peer_evidence(actor,p_target_id) then
        raise exception 'Safety report unavailable' using errcode='42501'; end if;
      target_type:='user'; resolved_target:=p_target_id;
    else
      select h.host_id into resolved_target from public.hangout_participants p
        join public.hangouts h on h.id=p.hangout_id
        where p.hangout_id=p_target_id and p.account_id=actor;
      if not found then raise exception 'Safety report unavailable' using errcode='42501'; end if;
      if p_target_mode='hangout_host' then
        target_type:='user'; provenance:='retained_host';
        provenance_ref:=p_target_id;
      else
        target_type:='hangout'; resolved_target:=p_target_id;
        provenance:='retained_hangout'; provenance_ref:=p_target_id;
      end if;
    end if;
  elsif p_target_mode='user' then
    campus:=private.people_ready_campus();
    if not private.pilot_capability_enabled('people') or not private.people_enabled() or campus is null
      or not private.people_visible(p_target_id,campus) then
      raise exception 'Safety report unavailable' using errcode='42501'; end if;
    target_type:='user'; resolved_target:=p_target_id;
    provenance:='current_people'; provenance_ref:=p_target_id;
  else
    if not private.hangouts_enabled() or not private.can_read_hangout(p_target_id,false) then
      raise exception 'Safety report unavailable' using errcode='42501'; end if;
    target_type:='hangout'; resolved_target:=p_target_id;
    provenance:='current_hangout'; provenance_ref:=p_target_id;
  end if;
  if target_type='user' and resolved_target=actor then
    raise exception 'Safety report unavailable' using errcode='42501'; end if;

  -- Inclusive lower edge: a row at exactly now-1 hour still consumes a slot.
  -- The clock is sampled after contention and after final authorization.
  saved_at:=clock_timestamp();
  if (select count(*) from private.safety_reports r where r.reporter_id=actor
      and r.submitted_at between saved_at-interval '1 hour' and saved_at)>=5 then
    raise exception 'Safety report unavailable' using errcode='42501'; end if;
  insert into private.safety_reports(reporter_id,target_type,target_id,category,narrative,
    provenance_kind,provenance_ref_id,submitted_at)
    values(actor,target_type,resolved_target,normalized_category,normalized_narrative,
      provenance,provenance_ref,saved_at) returning id into saved_id;
  insert into private.safety_report_requests(reporter_id,request_id,input_fingerprint,report_id)
    values(actor,p_request_id,input_fingerprint,saved_id);
  return query select saved_id,saved_at;
end;

declare actor uuid := auth.uid(); pair private.dm_pairs%rowtype;
  normalized text; message_id uuid; fingerprint text; old_retry private.dm_retries%rowtype;
begin
  perform private.social_hangout_mutation_lock();
  perform private.people_require_read_committed();
  if actor is null or p_peer_id is null or p_peer_id=actor or p_generation_id is null
    or p_action is null or p_action not in ('accept','reply','ignore','withdraw','close')
    or not private.dm_enabled() or not private.dm_active_caller() then
    raise exception 'DM unavailable' using errcode='42501'; end if;
  if p_action='reply' and p_reply_request_id is not null then
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      'dm-request:'||actor::text||':'||p_reply_request_id::text,0));
  end if;
  perform private.friendship_lock_pair(actor,p_peer_id);
  perform 1 from private.dm_feature_gate where singleton for share;
  if p_action in ('accept','reply') then
    perform private.dm_lock_evidence(actor,p_peer_id);
  end if;
  if not private.dm_enabled() or not private.dm_active_caller() then
    raise exception 'DM unavailable' using errcode='42501'; end if;
  select * into pair from private.dm_pairs d where d.generation_id=p_generation_id
    and d.low_id=least(actor,p_peer_id) and d.high_id=greatest(actor,p_peer_id)
    and d.state in ('pending','accepted');
  if p_action='reply' and p_reply_request_id is not null and p_reply_body is not null then
    normalized := private.profile_trim(p_reply_body);
    if length(normalized) not between 1 and 2000 then
      raise exception 'Invalid DM body' using errcode='22023'; end if;
    fingerprint := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(normalized,'UTF8')),'hex');
    select * into old_retry from private.dm_retries r
      where r.actor_id=actor and r.request_id=p_reply_request_id;
    if found then
      if old_retry.kind <> 'reply' or old_retry.target_id <> p_peer_id
        or old_retry.generation_id <> p_generation_id or old_retry.fingerprint <> fingerprint then
        raise exception 'DM request conflict' using errcode='23505'; end if;
      if pair.generation_id is null or pair.state <> 'accepted'
        or not private.dm_eligible(p_peer_id) then
        raise exception 'DM unavailable' using errcode='42501'; end if;
      return true;
    end if;
  end if;
  if pair.generation_id is null or not ((p_action in ('accept','reply','ignore') and pair.state='pending'
        and pair.initiator_id=p_peer_id)
      or (p_action='withdraw' and pair.state='pending' and pair.initiator_id=actor)
      or (p_action='close' and pair.state='accepted')) then
    raise exception 'DM unavailable' using errcode='42501'; end if;
  if p_action in ('accept','reply') then
    if not private.dm_eligible(p_peer_id) then
      raise exception 'DM unavailable' using errcode='42501'; end if;
    if p_action='reply' then
      if p_reply_request_id is null or p_reply_body is null then
        raise exception 'Invalid DM body' using errcode='22023'; end if;
      normalized := private.profile_trim(p_reply_body);
      if length(normalized) not between 1 and 2000 then
        raise exception 'Invalid DM body' using errcode='22023'; end if;
      insert into private.dm_messages(generation_id,sequence,author_id,body)
        values(pair.generation_id,pair.next_sequence,actor,normalized) returning id into message_id;
      update private.dm_pairs d set next_sequence=next_sequence+1
        where d.generation_id=pair.generation_id;
      insert into private.dm_retries(actor_id,request_id,kind,target_id,generation_id,message_id,fingerprint)
        values(actor,p_reply_request_id,'reply',p_peer_id,pair.generation_id,message_id,
          pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(normalized,'UTF8')),'hex'));
    elsif p_reply_request_id is not null or p_reply_body is not null then
      raise exception 'DM unavailable' using errcode='42501';
    end if;
    update private.dm_pairs d set state='accepted' where d.generation_id=pair.generation_id;
  else
    update private.dm_pairs d set state=case p_action when 'ignore' then 'ignored'
      when 'withdraw' then 'withdrawn' else 'closed' end
      where d.generation_id=pair.generation_id;
    insert into private.dm_suppression(initiator_id,recipient_id)
      values(pair.initiator_id,case when pair.initiator_id=pair.low_id
        then pair.high_id else pair.low_id end) on conflict do nothing;
  end if;
  return true;
end;

declare actor uuid := auth.uid();
declare pair private.friendships%rowtype;
begin
  perform private.social_hangout_mutation_lock();
  perform private.people_require_read_committed();
  if actor is null or p_peer_id is null or actor = p_peer_id or p_generation_id is null
    or p_action not in ('accept','decline','cancel','unfriend') or p_action is null
    or not private.friendship_enabled() or not private.people_active_owner() then
    raise exception 'Friendship unavailable' using errcode = '42501';
  end if;
  perform private.friendship_lock_pair(actor,p_peer_id);
  perform 1 from private.friendship_feature_gate where singleton for share;
  if p_action = 'accept' then
    perform private.friendship_lock_eligibility(actor,p_peer_id);
  end if;
  if not private.friendship_enabled() or not private.people_active_owner() then
    raise exception 'Friendship unavailable' using errcode = '42501';
  end if;
  select * into pair from private.friendships f
    where f.low_id = least(actor,p_peer_id) and f.high_id = greatest(actor,p_peer_id)
      and f.generation_id = p_generation_id;
  if not found or not (
    (p_action = 'accept' and pair.state = 'pending' and pair.requester_id = p_peer_id)
    or (p_action = 'decline' and pair.state = 'pending' and pair.requester_id = p_peer_id)
    or (p_action = 'cancel' and pair.state = 'pending' and pair.requester_id = actor)
    or (p_action = 'unfriend' and pair.state = 'accepted')) then
    raise exception 'Friendship unavailable' using errcode = '42501';
  end if;
  if p_action = 'accept' then
    if not private.friendship_eligible(p_peer_id)
      or private.people_ready_campus() <> pair.campus_id then
      raise exception 'Friendship unavailable' using errcode = '42501';
    end if;
    update private.friendships f set state = 'accepted'
      where f.low_id = pair.low_id and f.high_id = pair.high_id;
  else
    delete from private.friendships f where f.low_id = pair.low_id and f.high_id = pair.high_id;
    if p_action in ('decline','cancel') then
      insert into private.friendship_suppression(requester_id,recipient_id)
        values(pair.requester_id,case when pair.requester_id = pair.low_id
          then pair.high_id else pair.low_id end) on conflict do nothing;
    end if;
  end if;
  return true;
end;

declare actor uuid; c private.moderation_cases%rowtype; old_state text;
  old_revision bigint; new_state text; new_disposition text; normalized_note text;
  fingerprint text; prior private.moderation_requests%rowtype;
  r private.safety_reports%rowtype; duplicate private.safety_reports%rowtype;
  subject_campus uuid;
begin
  actor:=private.moderation_actor();
  if p_report_id is null or p_request_id is null or p_expected_revision is null
    or p_expected_revision<0 or p_action is null or p_action not in
      ('start_review','annotate','close_no_action','close_duplicate','reopen')
    or not private.moderation_report_allowed(actor,p_report_id,true) then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  normalized_note:=nullif(private.profile_trim(p_note),'');
  if (p_action='start_review' and (normalized_note is not null or p_duplicate_report_id is not null))
    or (p_action<>'start_review' and (normalized_note is null or length(normalized_note)>2000))
    or (p_action<>'close_duplicate' and p_duplicate_report_id is not null) then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  select * into r from private.safety_reports where id=p_report_id;
  if r.target_type='user' and exists(select 1 from public.platform_roles
      where user_id=r.target_id) then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  fingerprint:=md5(jsonb_build_array(p_report_id,p_expected_revision,p_action,
    normalized_note,p_duplicate_report_id)::text);
  -- Retry identity is locked before case revision. One operator's concurrent
  -- same-key call waits here; distinct operators serialize on the case row.
  perform pg_advisory_xact_lock(hashtextextended(actor::text||p_request_id::text,17017));
  select * into prior from private.moderation_requests
    where operator_id=actor and request_id=p_request_id;
  if found then
    if prior.fingerprint<>fingerprint then
      raise exception 'Moderation unavailable' using errcode='42501'; end if;
    case_state:=prior.result_state; revision:=prior.result_revision; return next; return;
  end if;
  if p_action='close_duplicate' then
    if p_duplicate_report_id=p_report_id
      or not private.moderation_report_allowed(actor,p_duplicate_report_id,true) then
      raise exception 'Moderation unavailable' using errcode='42501'; end if;
    select * into duplicate from private.safety_reports where id=p_duplicate_report_id;
    if duplicate.target_type<>r.target_type or duplicate.target_id<>r.target_id
      or (duplicate.submitted_at,duplicate.id)>=(r.submitted_at,r.id) then
      raise exception 'Moderation unavailable' using errcode='42501'; end if;
  end if;
  select * into c from private.moderation_cases where report_id=p_report_id for update;
  old_state:=coalesce(c.state,'open'); old_revision:=coalesce(c.revision,0);
  if old_revision<>p_expected_revision then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  if (p_action='start_review' and old_state<>'open')
    or (p_action in ('annotate','close_no_action','close_duplicate') and old_state<>'in_review')
    or (p_action='reopen' and old_state<>'closed') then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  new_state:=case when p_action in ('close_no_action','close_duplicate') then 'closed'
    else 'in_review' end;
  new_disposition:=case p_action when 'close_no_action' then 'no_action'
    when 'close_duplicate' then 'duplicate' else null end;
  if old_state='open' then
    insert into private.moderation_cases(report_id,state,revision,note,disposition,duplicate_report_id)
      values(p_report_id,new_state,1,normalized_note,new_disposition,p_duplicate_report_id);
  else
    update private.moderation_cases set state=new_state,revision=old_revision+1,
      note=normalized_note,disposition=new_disposition,duplicate_report_id=p_duplicate_report_id
      where report_id=p_report_id;
  end if;
  case_state:=new_state; revision:=old_revision+1;
  insert into private.moderation_requests(operator_id,request_id,fingerprint,report_id,
    result_state,result_revision) values(actor,p_request_id,fingerprint,p_report_id,
    case_state,revision);
  if r.target_type='user' then
    select m.university_id into subject_campus from public.university_memberships m
      where m.user_id=r.target_id for share;
  else
    select h.university_id into subject_campus from public.hangouts h
      where h.id=r.target_id;
  end if;
  insert into private.moderation_audit(operator_id,action,report_id,
    subject_target_type,subject_target_id,subject_campus_id,request_id,
    previous_state,new_state,previous_revision,new_revision,reason,duplicate_report_id)
    values(actor,p_action,p_report_id,r.target_type,r.target_id,subject_campus,
      p_request_id,old_state,new_state,old_revision,revision,
      normalized_note,p_duplicate_report_id);
  return next;
end;
